function follow(id){const p=players.find(p=>p.id===id);if(!p.visible&&p.age<18){S.notifications.unshift({type:'contactos',text:`Solicitud de seguimiento pendiente para ${p.name}.`});save();toast('Solicitud enviada. El jugador o tutor debe aceptarla.')}else{toggle('follows',id);toast(S.follows.includes(id)?'Ahora sigues este perfil':'Has dejado de seguirlo')}}
function profile(){if(S.role==='child'&&selected===1)selected=4;if(S.role==='teen'&&selected===1)selected=2;if(entity()&&view==='profile'&&selected===1)return orgprofile();if(['scout','coach','staff'].includes(S.role)&&selected===1)return proprofile();const p=players.find(p=>p.id===selected)||players[0],own=(selected===1&&S.role==='player'||selected===2&&S.role==='teen'||selected===4&&S.role==='child'),name=own&&S.role==='player'?S.profile.name:p.name,club=own&&S.role==='player'?S.profile.club:p.club,priv=p.age<18&&!p.visible&&!own&&S.role!=='family',t=tab||'Vídeos';return `<div class="profile-page-top"><div><span class="eyebrow">Perfil de jugador</span><h1>${esc(name).toUpperCase()}.</h1><p class="meta">${esc(p.position)} · ${p.age} años · ${esc(p.province)}</p></div>${btn('•••',`report('Perfil ${esc(p.name)}')`,'profile-menu')}</div><div class="profile-main-card"><div class="profile-portrait">${esc(name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div class="profile-card-info"><span class="available">DISPONIBLE PARA PRUEBAS</span><h2>${esc(club)}</h2><p>${p.height} cm · Pierna ${esc(p.foot.toLowerCase())} · ${esc(p.category)}</p><strong>${esc(p.position)}${p.secondary?' · '+esc(p.secondary):''}</strong></div></div><div class="profile-social-stats"><div><strong>${S.videos.filter(v=>v.status==='Publicado').length}</strong><span>Publicaciones</span></div><div><strong>0</strong><span>Seguidores</span></div><div><strong>${S.follows.length}</strong><span>Seguidos</span></div></div><div class="profile-actions">${own?btn('Editar perfil',"go('profileedit')",'primary'):btn(S.follows.includes(p.id)?'Siguiendo':'Seguir',`follow(${p.id})`,'primary')}${btn('Compartir',`share('${esc(p.name)}','profile',${p.id})`)}${btn('QR',`share('${esc(p.name)}','profile',${p.id})`)}${pro()?btn('Acciones TALNT',`actionForm(${p.id})`,'primary')+btn(S.saved.includes(p.id)?'Guardado':'Guardar jugador',`toggle('saved',${p.id})`):!own?btn('Mensaje',`peerMessage(${p.id})`):''}</div>${priv?notice('Perfil privado. Envía una solicitud de seguimiento para acceder a su contenido.'):`${tabs(['Vídeos','Estadísticas','Trayectoria','Info'],t)}${t==='Vídeos'?`<div class="profile-feed-header"><div><h3>Vídeos</h3><p class="meta">Highlights, partidos y entrenamientos</p></div>${own?btn('Gestionar fijados',"go('myvideos')",'manage-pins'):''}</div><div class="profile-feed-grid">${S.videos.filter(v=>v.status==='Publicado').sort((a,b)=>b.pin-a.pin).map((v,i)=>`<button class="profile-video video-thumb-${i%4}" onclick="feed=${S.videos.filter(v=>v.status==='Publicado').findIndex(x=>x.id===v.id)};go('home')">${runtimeMedia[v.id]?`<video src="${runtimeMedia[v.id]}" muted preload="metadata"></video>`:''}${v.pin?'<span class="pin-label">FIJADO</span>':''}<span class="thumb-type">${esc(v.type)}</span><span class="play-count">▷ ${v.views.toLocaleString('es-ES')}</span></button>`).join('')}</div>`:t==='Estadísticas'?statsBlock(own):t==='Trayectoria'?`<div class="card timeline"><span class="eyebrow">${esc(S.stats.season)}</span><h2>${esc(S.stats.club)}</h2><p>${esc(S.stats.category)} · ${S.stats.games} partidos</p><small>Datos introducidos por el jugador · no verificados</small></div>`:`<div class="card"><h2>Información deportiva</h2><p>${esc(own?S.profile.bio:'Disponible para pruebas. Perfil deportivo de demostración.')}</p><p>Pierna: ${p.foot}<br>Altura: ${p.height} cm<br>Nacionalidad: ${p.nationality}</p>${badge('Disponible para pruebas')}</div>`}<div class="referral-card"><div class="referral-icon">↗</div><div><h3>Comparte tu perfil</h3><p class="meta">Invita a tus amigos a conocer TALNT con tu enlace o código QR.</p>${btn('Copiar enlace',`copy(location.origin+location.pathname+'#profile?id=${p.id}')`,'ghost')}<small>Las recompensas por invitaciones llegan en una fase posterior.</small></div></div>`}` }
function statsBlock(own=true){const s=S.stats;return `<div class="card"><div class="row between"><h2>Temporada ${esc(s.season)}</h2>${badge('No verificadas',true)}</div><p>${esc(s.club)} · ${esc(s.category)}</p><div class="stats">${[['Partidos',s.games],['Titularidades',s.starts],['Minutos',s.minutes],['Goles',s.goals],['Asistencias',s.assists],['Tarjetas',s.cards]].map(([n,v])=>`<div><strong class="metric">${v}</strong><small>${n}</small></div>`).join('')}</div><p><small>Última actualización: ${esc(s.updated)}. Datos aportados por el jugador o tutor.</small></p>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener">Consultar ficha federativa</a>`:'<p class="muted">Ficha federativa todavía no añadida.</p>'}${own?btn('Editar estadísticas',"go('statsedit')"):''}</div>`}
function orgprofile(){const names=['Club Demo Palma','Academia Demo Madrid','Agencia Demo Sport'],idx=view==='profile'&&entity()?['club','academy','agency'].indexOf(S.role):Math.max(0,Math.min(2,selected-1)),name=names[idx],t=tab||'Inicio';return `<div class="cover">${badge(['Club','Academia','Agencia'][idx])}<h1>${name}</h1><p>${['Palma · Baleares','Madrid','Barcelona'][idx]}</p><div class="row">${btn('Seguir',`toast('Ahora sigues a ${name}')`)}${btn('Compartir / QR',`share('${name}','orgprofile',${idx+1})`)}</div></div>${tabs(['Inicio','Plantillas','Oportunidades','Vídeos','Info'],t)}${t==='Plantillas'?`<div class="card"><h2>Infantil · Juvenil · Sénior</h2>${players.filter(p=>p.club===name).map(p=>`<div class="list-row"><div>${esc(p.name)} · ${esc(p.category)}<p><small>Vinculación ${S.audit.some(a=>a.text.includes(p.name+' vinculación'))?'confirmada':'pendiente de confirmar'}</small></p></div>${entity()?btn('Confirmar vinculación',`log('${p.name} vinculación confirmada');render();toast('Plantilla confirmada')`):btn('Ver perfil',`go('profile',${p.id})`)}</div>`).join('')||'<p>No hay jugadores vinculados todavía.</p>'}</div>`:t==='Oportunidades'?opCards(S.ops.filter(o=>o.org===name)):t==='Vídeos'?`<div class="card"><h2>Vídeos de la entidad</h2><p>Publica un vídeo para completar la presentación de tu equipo.</p>${entity()?btn('Publicar vídeo',"go('upload')") :''}</div>`:`<div class="card"><h2>${t==='Info'?'Información de la entidad':'Fútbol y oportunidades'}</h2><p>Entidad ficticia para recorrer los flujos del MVP.</p><p>Categorías: infantil, cadete, juvenil y sénior.</p><p>Responsable de captación: contacto de demostración.</p>${btn('Ver oportunidades',"go('opportunities')")}</div>`}`}
function proprofile(){const role=['scout','coach','staff'].includes(S.role)?roles[S.role]:'Scouter';return `<div class="cover">${badge(role)}<h1>Marcos Vidal</h1><p>Captación · Club Demo Valencia</p>${btn('Seguir',"toast('Ahora sigues a Marcos')")} ${btn('Mensaje',"selected=1;go('chat')")}</div><div class="card"><h2>Ficha profesional</h2><p>Zona de scouting: Comunidad Valenciana y Baleares.</p><p>Categorías: cadete, juvenil y sénior.</p><p>Experiencia de demostración: seguimiento de fútbol base y coordinación de captación.</p></div>`}
function opportunities(){const t=tab||'Para ti';let ops=S.ops.filter(o=>o.status==='Activa');if(!['Para ti','Guardadas'].includes(t))ops=ops.filter(o=>o.type===t);if(t==='Guardadas')ops=ops.filter(o=>S.savedOps.includes(o.id));if(filter.opq)ops=ops.filter(o=>(o.title+' '+o.province+' '+o.category).toLowerCase().includes(filter.opq.toLowerCase()));return `<span class="eyebrow">El siguiente paso</span><div class="row between"><h1>ENCUENTRA TU<br>SIGUIENTE PASO.</h1><div class="row">${btn('Mis solicitudes',"go('applications')")}${entity()?btn('＋ Publicar',"opForm()",'primary'):''}</div></div>${tabs(['Para ti','Pruebas','Equipos','Campus','Torneos','Guardadas'],t)}<label>Buscar por título, provincia o categoría<input value="${esc(filter.opq||'')}" onchange="filter.opq=this.value;render()" placeholder="Ej. Juvenil, Valencia"></label>${btn('Filtros',"opFilters()")}${opCards(ops)}${entity()?`<h2>Gestionar publicaciones</h2>${S.ops.map(o=>`<div class="list-row"><div><strong>${esc(o.title)}</strong><p><small>${esc(o.status)}</small></p></div>${btn('Gestionar candidaturas',`go('candidates',${o.id})`)}</div>`).join('')}`:''}`}
function opCards(ops){if(filter.opProvince)ops=ops.filter(o=>o.province===filter.opProvince);if(filter.opCategory)ops=ops.filter(o=>o.category===filter.opCategory);return `<div class="opportunity-list">${ops.map(o=>`<article class="card opportunity-card"><div class="opportunity-card-top"><span class="opportunity-type">${esc(o.type).toUpperCase()}</span><small>Cierre: ${esc(o.deadline)}</small></div><h3>${esc(o.title)}</h3><div class="opportunity-club">${esc(o.org)} · ${esc(o.province)}</div><p>${esc(o.desc)}</p><div class="opportunity-tags"><span>${esc(o.category)}</span><span>${o.min}–${o.max} años</span><span>${esc(o.position)}</span></div><div class="opportunity-facts"><small>${esc(o.date)}</small><strong>${esc(o.price)}</strong></div><div class="opportunity-card-actions">${btn('Ver oportunidad',`go('opdetail',${o.id})`,'opportunity-apply')}${btn(S.savedOps.includes(o.id)?'▣':'⌑',`toggle('savedOps',${o.id})`,'bookmark')}</div></article>`).join('')||'<div class="empty">No hay oportunidades con estos criterios.</div>'}</div>`}
function opFilters(){modal({title:'Filtros de oportunidades',body:`<form onsubmit="event.preventDefault();Object.assign(filter,data(this));document.querySelector('#modal').close();render()">${select('opProvince','Provincia',['','Baleares','Valencia','Madrid','Barcelona'],filter.opProvince)}${select('opCategory','Categoría',['','Infantil','Cadete','Juvenil','Sénior'],filter.opCategory)}${btn('Aplicar','','primary')}${btn('Limpiar',"delete filter.opProvince;delete filter.opCategory;document.querySelector('#modal').close();render()")}</form>`})}
function opdetail(){const o=S.ops.find(o=>o.id===selected)||S.ops[0];return `<div class="secondary-nav">${btn('Volver a oportunidades',"go('opportunities')")}${btn(S.savedOps.includes(o.id)?'Guardada':'Guardar',`toggle('savedOps',${o.id})`)}${btn('Compartir',`share('${esc(o.title)}','opdetail',${o.id})`)}</div><div class="cover">${badge(o.type)}<h1>${esc(o.title)}</h1><p><a href="#orgprofile" onclick="selected=1">${esc(o.org)}</a> · ${badge('Entidad verificada')}</p></div><div class="grid two"><div class="card"><h2>La oportunidad</h2><p>${esc(o.desc)}</p><p>Categoría: ${esc(o.category)}<br>Edades: ${o.min}–${o.max}<br>Posiciones: ${esc(o.position)}<br>Plazas: ${o.places}<br>Fecha: ${esc(o.date)}<br>Cierre de solicitudes: ${esc(o.deadline)}</p><strong>${esc(o.price)}</strong>${notice('El precio es informativo. La inscripción y el pago se acuerdan directamente con el organizador.')}</div><div class="card"><h2>Dónde</h2><p>${esc(o.location)}</p><div class="notice">Ubicación de demostración. El mapa muestra una zona orientativa, no un campo real.</div><iframe title="Mapa orientativo de la oportunidad" loading="lazy" style="width:100%;height:240px;border:0;border-radius:10px" src="https://www.openstreetmap.org/export/embed.html?bbox=-0.405%2C39.45%2C-0.345%2C39.49&layer=mapnik"></iframe><a href="https://www.openstreetmap.org/search?query=${encodeURIComponent(o.province)}" target="_blank" rel="noopener">Abrir mapa de la provincia</a><h2 style="margin-top:30px">Tu candidatura</h2><p>Se enviarán tu perfil y tus vídeos fijados.</p>${['player','teen','child','family'].includes(S.role)?btn(S.applications.some(a=>a.op===o.id)?'Ver solicitud':S.role==='child'?'Preparar solicitud':'Solicitar',S.applications.some(a=>a.op===o.id)?"go('applications')":`applyForm(${o.id})`,'primary'):entity()?btn('Gestionar candidatos',`go('candidates',${o.id})`):notice('Las solicitudes están disponibles para jugadores y sus familias.')}</div></div>`}
function applyForm(id){if(!guard())return;modal({title:S.role==='child'?'Preparar solicitud':'Solicitar oportunidad',body:`<form onsubmit="event.preventDefault();sendApplication(this,${id})"><p>Perfil y hasta tres vídeos fijados incluidos.</p>${area('message','Mensaje opcional')}${S.role==='family'?select('child','Jugador',S.children.map(c=>c.name)):''}${S.role==='child'?notice('Tu tutor deberá confirmar esta solicitud antes de enviarla.'):''}${btn(S.role==='child'?'Enviar al tutor':'Enviar candidatura','','primary')}</form>`})}
function sendApplication(f,id){S.applications.push({id:Date.now(),op:id,name:S.role==='child'?S.children[0].name:S.role==='family'?data(f).child:S.profile.name,message:data(f).message,status:S.role==='child'?'Pendiente del tutor':'Enviada'});S.notifications.unshift({type:'oportunidades',text:S.role==='child'?'Solicitud preparada. Falta confirmación del tutor.':'Tu candidatura se ha enviado.'});save();$('#modal').close();go('applications');toast('Solicitud guardada')}
function applications(){return `<h1>Mis solicitudes</h1>${S.applications.map(a=>{const o=S.ops.find(o=>o.id===a.op);return `<div class="card"><div class="row between"><h2>${esc(o?.title||'Oportunidad')}</h2>${badge(a.status)}</div><p>${esc(a.name)}</p><p>${esc(a.message)}</p><small>Estados: Enviada → Visto → Preseleccionado → Invitado → Cerrada / No seleccionado.</small><div class="row" style="margin-top:15px">${btn('Ver oportunidad',`go('opdetail',${a.op})`)}${a.status==='Pendiente del tutor'&&S.role==='family'?btn('Confirmar envío',`setApplication(${a.id},'Enviada')`,'primary'):''}</div></div>`}).join('')||`<div class="empty">Todavía no has solicitado ninguna oportunidad.<p>${btn('Explorar oportunidades',"go('opportunities')",'primary')}</p></div>`}`}
function setApplication(id,status){const a=S.applications.find(a=>a.id===id);a.status=status;S.notifications.unshift({type:'oportunidades',text:`Candidatura de ${a.name}: ${status}.`});log(`Candidatura ${id}: ${status}`);render();toast('Estado actualizado')}
function candidates(){if(!entity()&&S.role!=='admin')return notice('La gestión de candidaturas corresponde a clubes, academias y agencias.');const o=S.ops.find(o=>o.id===selected)||S.ops[0];const apps=S.applications.filter(a=>a.op===o.id&&a.status!=='Pendiente del tutor').filter(a=>!tab||tab==='Todas'||a.status===tab);return `<span class="eyebrow">Gestión de candidaturas</span><h1>${esc(o.title)}</h1><div class="row">${badge(o.status)}${btn('Editar',`opForm(${o.id})`)}${btn(o.status==='Pausada'?'Reactivar':'Pausar',`setOp(${o.id},'${o.status==='Pausada'?'Activa':'Pausada'}')`)}${btn('Cerrar',`setOp(${o.id},'Cerrada')`,'danger')}</div>${tabs(['Todas','Enviada','Visto','Preseleccionado','Invitado','No seleccionado'],tab||'Todas')} ${apps.map(a=>`<div class="card"><h2>${esc(a.name)}</h2>${badge(a.status)}<p>${esc(a.message)||'Sin mensaje adicional.'}</p><p><small>Perfil y vídeos fijados adjuntos.</small></p><div class="row">${btn('Ver perfil',`setApplication(${a.id},'Visto');go('profile',1)`)}${btn('Preseleccionar',`setApplication(${a.id},'Preseleccionado')`)}${btn('Invitar',`setApplication(${a.id},'Invitado');actionForm(1,'Invitar a prueba')`,'primary')}${btn('Descartar',`setApplication(${a.id},'No seleccionado')`,'danger')}</div></div>`).join('')||'<div class="empty">Todavía no hay candidaturas en este estado. Puedes enviar una desde el modo Jugador.</div>'}`}
function setOp(id,status){S.ops.find(o=>o.id===id).status=status;log(`Oportunidad ${id}: ${status}`);render();toast('Publicación actualizada')}
function opForm(id){if(!entity()&&S.role!=='admin')return;const o=S.ops.find(o=>o.id===id)||{};modal({title:id?'Editar oportunidad':'Publicar oportunidad',body:`<form onsubmit="event.preventDefault();saveOp(this,${id||0})"><div class="fields">${select('type','Tipo',['Pruebas','Equipos','Campus','Torneos'],o.type)}${input('title','Título',o.title||'')}${select('category','Categoría',['Infantil','Cadete','Juvenil','Sénior'],o.category)}${input('min','Edad mínima',o.min||14,'number')}${input('max','Edad máxima',o.max||18,'number')}${input('position','Posiciones buscadas',o.position||'Todas')}${input('date','Fecha',o.date||'','date')}${input('deadline','Fecha límite',o.deadline||'','date')}${input('places','Plazas',o.places||10,'number')}${input('price','Precio informativo',o.price||'Gratis')}${select('province','Provincia',['Baleares','Valencia','Madrid','Barcelona'],o.province)}${input('location','Ubicación',o.location||'')}</div>${area('desc','Requisitos y descripción',o.desc||'')}${btn('Guardar oportunidad','','primary')}</form>`})}function saveOp(f,id){const d=data(f);if(+d.min>+d.max||d.deadline>d.date){toast('Revisa las edades y la fecha límite.');return}if(id)Object.assign(S.ops.find(o=>o.id===id),d);else S.ops.unshift({...d,id:Date.now(),org:'Club Demo Palma',status:'Activa'});save();$('#modal').close();go('opportunities');toast('Oportunidad guardada')}
function messages(){let rs=S.requests.filter(r=>!S.blocked.includes(r.from));const t=tab||'Todos';if(t==='No leídos')rs=rs.filter(r=>r.status==='Pendiente');if(t==='Jugadores')rs=[];if(t==='Scouters')rs=rs.filter(r=>r.from.includes('Scouter'));return `<div class="row between"><h1>MENSAJES.</h1>${btn('Nuevo mensaje',"newMessage()")}</div>${tabs(['Todos','No leídos','Clubes','Scouters','Jugadores'],t)}<h2>Solicitudes pendientes</h2>${rs.filter(r=>r.status==='Pendiente').map(r=>requestCard(r)).join('')||'<p class="muted">No hay solicitudes pendientes.</p>'}<h2 style="margin-top:28px">Conversaciones</h2>${rs.filter(r=>r.status==='Aceptada').map(r=>`<div class="card"><div class="row between"><div><h3>${esc(r.from)}</h3>${badge('Club')}<p>${esc(r.player)} · ${esc((S.chats[r.id]||[]).at(-1)?.text||'Invitación aceptada. Ya podéis conversar.')}</p></div>${btn('Abrir chat',`go('chat',${r.id})`)}</div></div>`).join('')||'<div class="empty">Acepta una solicitud para abrir una conversación.</div>'}`}
function requestCard(r){const decide=S.role==='family'&&r.age<14||['player','teen'].includes(S.role)&&r.age>=14;return `<div class="card"><div class="row between"><div><h3>${esc(r.from)}</h3>${badge('Club')} ${badge(r.status)}</div>${btn('Ver entidad',"go('orgprofile',1)")}</div><p>${esc(r.type)} · Para ${esc(r.player)}</p><p>${esc(r.team)} · ${esc(r.category)}<br>${esc(r.date)} · ${esc(r.time)}<br>${esc(r.location)}</p><p>${esc(r.message)}</p>${r.age<14?notice('Decide el tutor. Hasta su aprobación, el profesional no puede escribir. El tutor podrá leer la conversación.'):notice('Hasta aceptar la acción TALNT, no se abre el chat.')}<div class="row">${decide&&r.status==='Pendiente'?btn('Aceptar',`requestDecision(${r.id},'Aceptada')`,'primary')+btn('Rechazar',`requestDecision(${r.id},'Rechazada')`):''}${btn('Denunciar / bloquear',`report('${esc(r.from)}')`)}</div></div>`}
function requestDecision(id,status){S.requests.find(r=>r.id===id).status=status;S.notifications.unshift({type:'contactos',text:`Solicitud ${status.toLowerCase()}.`});log(`Solicitud ${id}: ${status}`);render();toast(status==='Aceptada'?'Contacto aprobado. Conversación disponible.':'Solicitud rechazada')}
function newMessage(){modal({title:'Nuevo contacto',body:`<p>${pro()?'Selecciona un jugador para enviar una acción TALNT.':'Entre jugadores solo se puede escribir si se siguen mutuamente.'}</p>${players.map(p=>`<div class="list-row"><strong>${esc(p.name)}</strong>${btn(pro()?'Contactar':'Mensaje',pro()?`actionForm(${p.id})`:`peerMessage(${p.id})`)}</div>`).join('')}`})}
function peerMessage(id){if(!S.follows.includes(id)){toast('Primero debéis seguiros mutuamente.');return}modal({title:'Seguimiento mutuo',body:`<p>En esta demo puedes simular que el otro jugador acepta seguirte.</p>${btn('Simular seguimiento mutuo',`peerChat(${id})`,'primary')}`})}function peerChat(id){const p=players.find(p=>p.id===id);const r={id:Date.now(),player:S.profile.name,age:18,from:p.name,type:'Contacto entre jugadores',status:'Aceptada'};S.requests.push(r);save();$('#modal').close();go('chat',r.id)}
function actionForm(id,type='Invitar a prueba'){if(!pro()){toast('Las acciones TALNT están disponibles para profesionales.');return}if(!guard())return;const p=players.find(p=>p.id===id);modal({title:'Acción TALNT',body:`<form onsubmit="event.preventDefault();sendAction(this,${id})"><p>Destinatario: <strong>${esc(p.name)}</strong></p>${p.age<14?notice('El tutor debe aprobar el contacto y podrá leer la conversación.'):notice('El jugador debe aceptar antes de recibir mensajes libres.')}<div class="fields">${select('type','Acción',['Solicitar información','Invitar a prueba','Pedir disponibilidad'],type)}${input('team','Equipo o entidad','Club Demo Palma')}${input('category','Categoría',p.category)}${input('date','Fecha','','date')}${input('time','Hora','17:30','time')}${input('location','Ubicación o modalidad','Campo municipal')}</div>${area('message','Información de la solicitud')}${btn('Enviar solicitud','','primary')}</form>`})}
function sendAction(f,id){const p=players.find(p=>p.id===id),d=data(f);S.requests.unshift({...d,id:Date.now(),player:p.name,age:p.age,from:roles[S.role]+' Demo Palma',status:'Pendiente'});S.notifications.unshift({type:'contactos',text:`Nueva ${d.type.toLowerCase()} para ${p.name}.`});save();$('#modal').close();go('messages');toast(p.age<14?'Enviada al tutor. Correo simulado.':'Solicitud enviada al jugador')}
function chat(){const r=S.requests.find(r=>r.id===selected);if(!r)return notice('Selecciona una conversación desde Mensajes.');if(r.status!=='Aceptada')return requestCard(r);const readonly=S.role==='family'&&r.age<14;return `<div class="row between"><div><span class="eyebrow">${esc(r.player)}</span><h1>${esc(r.from)}</h1></div>${btn('Opciones',`chatOptions(${r.id})`)}</div>${r.age<14?notice('El tutor de este jugador puede leer esta conversación.'+(readonly?' Estás en modo solo lectura.':'')):''}<div class="card"><h3>${esc(r.type)}</h3>${badge(r.status)}<p>${esc(r.date||'')} ${esc(r.time||'')} · ${esc(r.location||'')}</p><p>${esc(r.message||'Contacto aprobado.')}</p></div><div class="chat">${(S.chats[r.id]||[]).map((m,i)=>`<div class="bubble ${m.me?'me':''}">${esc(m.text)}<br><small>${esc(m.time)}</small> ${btn('⋯',`report('Mensaje ${i+1}')`,'ghost')}</div>`).join('')||'<p class="muted">La conversación ya está abierta.</p>'}</div>${!readonly?`<form id="chat-form"><label>Mensaje<input name="text" required placeholder="Escribe un mensaje"></label><div class="row">${btn('Enviar','','primary')}${btn('Adjuntar',"attachFile()")}${btn('Compartir perfil',`sendChatText(${r.id},'Perfil: '+location.origin+'/#profile')`)}${btn('Compartir oportunidad',`sendChatText(${r.id},'Oportunidad: '+S.ops[0].title)`)}${pro()?btn('Acción TALNT',"actionForm(1)"):''}</div></form>`:notice('Solo lectura. El jugador y el profesional son quienes conversan.')}`}
function sendChatText(id,text){(S.chats[id]??=[]).push({text,me:true,time:new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})});save();render()}function attachFile(){modal({title:'Adjuntar archivo',body:`<label>Archivo<input type="file" onchange="sendChatText(${selected},'Adjunto de demostración: '+this.files[0].name);document.querySelector('#modal').close()"></label><p class="muted">La demo guarda el nombre del archivo, sin enviarlo a un servidor.</p>`})}
function chatOptions(id){const r=S.requests.find(r=>r.id===id);modal({title:'Opciones de conversación',body:`<div class="row">${btn('Ver perfil',"document.querySelector('#modal').close();go('orgprofile',1)")}${btn('Silenciar',"document.querySelector('#modal').close();toast('Conversación silenciada')")}${btn('Denunciar y bloquear',`report('${esc(r.from)}')`)}</div>`})}
function family(){if(S.role!=='family')return notice('El panel de familia está disponible en el modo Tutor / familia.');return `<div class="row between"><div><span class="eyebrow">Tú acompañas. Ellos juegan.</span><h1>Mi familia</h1></div>${btn('＋ Añadir hijo',"go('childadd')",'primary')}</div>${S.children.map((c,i)=>`<div class="card"><div class="row between"><div class="row">${avatar(c.name)}<div><h2>${esc(c.name)}</h2><p>${c.age} años · ${esc(c.club)}</p></div></div>${badge(c.premium?'Premium activo':'Sin suscripción')}</div><label><input type="checkbox" ${c.visible?'checked':''} onchange="S.children[${i}].visible=this.checked;players[3].visible=this.checked;save();render()">Visible para clubes y scouters verificados</label><small>Por defecto, el perfil es privado. No puede abrirse a todo el mundo.</small><div class="row" style="margin-top:18px">${btn('Ver perfil',"go('profile',4)")}${btn('Suscripción',"go('premium')")}${btn('Editar estadísticas',"go('statsedit')")}${btn('Acceso del hijo',`childAccess(${i})`)}${c.age>=14?btn('Traspasar cuenta',`transferChild(${i})`):''}</div><h3 style="margin-top:22px">Solicitudes de contacto</h3>${S.requests.filter(r=>r.player===c.name&&r.status==='Pendiente').map(requestCard).join('')||'<p class="muted">Sin contactos pendientes.</p>'}<h3>Conversaciones (solo lectura)</h3>${S.requests.filter(r=>r.player===c.name&&r.status==='Aceptada').map(r=>btn(r.from,`go('chat',${r.id})`)).join('')||'<p class="muted">No hay conversaciones aprobadas.</p>'}</div>`).join('')}<h2>Solicitudes de oportunidades</h2>${S.applications.filter(a=>a.status==='Pendiente del tutor').map(a=>`<div class="card"><p>${esc(a.name)} · ${esc(S.ops.find(o=>o.id===a.op)?.title)}</p>${btn('Confirmar envío',`setApplication(${a.id},'Enviada')`,'primary')}${btn('Rechazar',`setApplication(${a.id},'Cerrada')`)}</div>`).join('')||'<p class="muted">Sin candidaturas pendientes de confirmación.</p>'}`}
function childAccess(i){modal({title:'Acceso del jugador',body:`<p>${esc(S.children[i].name)} dispone de acceso para publicar, ver vídeos y hablar con contactos aprobados.</p><p>No puede pagar, cambiar privacidad ni aprobar contactos.</p>${btn('Probar acceso del menor',"document.querySelector('#modal').close();changeRole('child')",'primary')}${btn('Simular que cumple 14 años',`S.children[${i}].age=14;save();document.querySelector('#modal').close();render()`)}`})}function transferChild(i){modal({title:'Traspaso al jugador',body:`<p>Al cumplir 14 años, el jugador completa su verificación y conserva vídeos, seguidores y estadísticas.</p>${btn('Simular traspaso',`S.children[${i}].transferred=true;save();document.querySelector('#modal').close();changeRole('teen');toast('Cuenta transferida. Contenido conservado.')`,'primary')}`})}
function notifications(){const t=tab||'Todas';return `<h1>Notificaciones</h1>${tabs(['Todas','Contactos','Oportunidades','Actividad','Suscripción'],t)}${S.notifications.filter(n=>t==='Todas'||n.type===t.toLowerCase()).map(n=>`<div class="card">${badge(n.type)}<p>${esc(n.text)}</p>${n.request?btn('Responder',`selected=${n.request};go('messages')`):btn('Ver',`go('${n.type==='oportunidades'?'applications':n.type==='suscripción'?'premium':'myvideos'}')`)}</div>`).join('')||'<div class="empty">No hay notificaciones en esta categoría.</div>'}`}
function settings(){return `<h1>Ajustes y privacidad</h1><div class="grid two"><div class="card"><h2>Visibilidad del perfil</h2>${S.role==='child'?notice('Tu tutor decide quién puede ver tu perfil.'): `<label>Quién puede verlo<select onchange="S.privacy[S.role]=this.value;if(S.role==='teen')players[1].visible=this.value!=='private';if(S.role==='player')players[0].visible=this.value!=='private';save();toast('Privacidad actualizada')">${[['private','Privado'],['pros','Profesionales verificados'],...(!['family'].includes(S.role)?[['public','Todo el mundo']]:[])].map(([v,n])=>`<option value="${v}" ${S.privacy[S.role]===v?'selected':''}>${n}</option>`).join('')}</select></label>`}<h3>Contacto y comentarios</h3><p class="muted">Los profesionales envían primero una acción TALNT. Entre jugadores, el seguimiento debe ser mutuo. En vídeos de menores solo comentan seguidores mutuos.</p><h3>Usuarios bloqueados</h3>${S.blocked.map(n=>`<p>${esc(n)} ${btn('Desbloquear',`S.blocked=S.blocked.filter(x=>x!=='${esc(n)}');save();render()`)}</p>`).join('')||'<p class="muted">No tienes usuarios bloqueados.</p>'}</div><div class="card"><h2>Cuenta</h2><div class="secondary-nav">${btn('Editar perfil',"go('profileedit')")}${S.role!=='child'?btn('TALNT Premium',"go('premium')"):''}${btn('Verificación',"go('verification')")}</div><h3>Sesiones y dispositivos</h3><p>Este navegador · sesión actual</p>${pro()?notice('Una sesión por cuenta profesional. La demo puede simular el cierre al entrar desde otro dispositivo.'):notice('El tutor y el jugador pueden utilizar sus accesos a la vez.')} ${pro()?btn('Simular acceso en otro dispositivo',"S.verified=false;save();go('login');toast('Sesión anterior cerrada en la demo')"):''}<h3 style="margin-top:25px">Preferencias de avisos</h3>${['Contactos','Oportunidades','Actividad'].map(n=>`<label><input type="checkbox" checked onchange="toast('Preferencia guardada')">${n}</label>`).join('')}${btn('Cerrar sesión',"changeRole('visitor')")}${S.role!=='child'?btn('Eliminar cuenta',"deleteAccount()",'danger'):''}</div></div><div class="card"><h2>Documentos legales</h2><p class="muted">El proveedor indica que debe redactarlos vuestro asesor legal. No se presentan textos de ejemplo como contratos válidos.</p><div class="row">${['Condiciones de uso','Privacidad','Consentimiento parental','Normas de la comunidad','Devoluciones'].map(n=>btn(n,`legal('${n}')`)).join('')}</div></div>`}
function legal(n){modal({title:n,body:notice('Documento pendiente de entrega por vuestro asesor legal. Esta demo muestra su ubicación y el flujo de aceptación, sin sustituir el texto definitivo.')})}function deleteAccount(){modal({title:'Eliminar cuenta',body:`<p>Esta acción elimina los datos locales de esta demo. No hay una cuenta real conectada.</p>${btn('Eliminar datos de la demo',"localStorage.removeItem('talnt-private-preview-v1');S=structuredClone(initial);S.role='visitor';save();document.querySelector('#modal').close();go('home')",'danger')}`})}
function report(target){modal({title:'Denunciar y bloquear',body:`<form onsubmit="event.preventDefault();sendReport(this,'${esc(target)}')"><p>Elemento: ${esc(target)}</p>${select('reason','Motivo',['Contacto inapropiado de un adulto con un menor','Contenido sexual o inapropiado','Acoso o amenazas','Suplantación','Spam','Otro'])}${area('details','Información adicional')}<label><input type="checkbox" name="block">Bloquear también este usuario</label><p class="muted">La persona denunciada no conocerá tu identidad.</p>${btn('Enviar denuncia','','primary')}</form>`})}function sendReport(f,target){const d=data(f);S.reports.unshift({id:Date.now(),target,...d,priority:d.reason.includes('menor'),status:'Pendiente'});if(d.block)S.blocked.push(target.replace('Perfil ',''));save();$('#modal').close();toast('Denuncia recibida. Puedes revisarla en el panel de administración.');render()}
function premium(){if(S.role==='child')return notice('Tu tutor gestiona la suscripción.');return `<span class="eyebrow">Una sola suscripción</span><h1>TALNT Premium</h1>${notice('Demo sin cobros. Los precios están pendientes de definir en el documento del proveedor.')}<div class="grid two"><div class="card"><h2>${S.premium?'Premium activo':'Activar Premium'}</h2><p>Publicación de vídeos, perfil deportivo, comunidad y oportunidades. Radar y scouting para profesionales.</p>${select('billing','Periodicidad',['Mensual','Anual con descuento'])}<p>${pro()?'Suscripción profesional.':'Primer mes gratis por jugador, también para cada hijo.'}</p>${S.role==='family'?S.children.map(c=>`<div class="list-row"><strong>${esc(c.name)}</strong>${badge(c.premium?'Activa':'Pendiente')}</div>`).join(''):''}<p class="muted">Precio pendiente · No se introducen datos de tarjeta.</p><div class="row">${btn('Simular activación',"S.premium=true;save();toast('Premium activado sin cobro');render()",'primary')}${btn('Restaurar compras',"S.premium=true;save();toast('Compra de demo restaurada');render()")}${btn('Simular cancelación',"S.premium=false;save();toast('Suscripción de demo cancelada');render()")}</div></div><div class="card"><h2>Gestionar suscripción</h2><p>En el producto móvil, la compra y la cancelación se gestionan desde Apple o Google.</p>${entity()?`<h3>Contratación web para entidades</h3><p>Datos de facturación y contratación con factura.</p><form id="billing-form">${input('name','Razón social')}${input('cif','CIF')}${input('address','Dirección fiscal')}${input('email','Email de facturación','','email')}${btn('Simular contratación con factura','','primary')}</form>`:notice('El pago de jugadores, familias y profesionales individuales se realiza dentro de la app móvil en el alcance del proveedor.')}</div></div>`}
function login(){return `<div class="compact"><span class="eyebrow">Vuelve al juego</span><h1>Iniciar sesión</h1><form id="login-form" class="card">${input('email','Email','','email')}${input('password','Contraseña','','password')}${btn('Entrar en la demo','','primary')} ${btn('Recuperar contraseña',"go('recovery')",'ghost')}</form>${btn('Crear cuenta',"go('register')")}${notice('Acceso de demostración: no se valida una contraseña real.')}</div>`}function recovery(){return `<div class="compact"><h1>Recuperar contraseña</h1><form id="recovery-form" class="card">${input('email','Email','','email')}${btn('Enviar enlace de demo','','primary')}</form>${btn('Volver al acceso',"go('login')")}</div>`}
function register(){return `<div class="compact"><span class="eyebrow">Paso ${regStep} de 4</span><h1>${['','Elige tu cuenta','Tus datos','Verifica tu identidad','Activa TALNT Premium'][regStep]}</h1><div class="progress"><span style="width:${regStep*25}%"></span></div>${regStep===1?`<div class="grid two">${Object.entries(roles).filter(([k])=>!['child','teen','visitor','admin'].includes(k)).map(([k,v])=>`<button class="account" onclick="regRole='${k}';regStep=2;render()"><strong>${v}</strong><small>${k==='family'?'Para jugadores de 6 a 13 años':k==='player'?'Cuenta propia desde los 14 años': 'Cuenta profesional'}</small></button>`).join('')}</div>`:regStep===2?`<form id="register-form" class="card">${input('name',regRole==='family'?'Nombre del tutor':'Nombre completo')}${input('email','Email','','email')}${input('password','Contraseña','','password')}${input('dob','Fecha de nacimiento','','date')}<label><input type="checkbox" name="terms" required>He revisado las condiciones y la privacidad de la demo.</label>${btn('Ver documentos',"legal('Condiciones y privacidad')",'ghost')}${btn('Continuar','','primary')}</form>`:regStep===3?verification(true):premium()}${regStep===4?btn(S.role==='family'?'Añadir mi primer hijo':'Entrar en TALNT',S.role==='family'?"go('childadd')":"go('home')",'primary'):''}${regStep>1?btn('Paso anterior',"regStep--;render()",'ghost'):''}</div>`}
function verification(inReg=false){const er=inReg?['club','academy','agency'].includes(regRole):entity();return `<div class="compact">${inReg?'':'<h1>Verificación de identidad</h1>'}${notice('Verificación simulada. No subas documentos personales reales. Didit y la revisión del equipo no están conectados.')}<form id="verify-form" class="card" data-register="${inReg}">${er?`${input('cif','CIF o licencia federativa (dato ficticio)')}${input('representative','Representante de la entidad')}`:`${select('document','Tipo de documento',['DNI','NIE','Pasaporte'])}${input('age','Edad devuelta por el documento (simulada)',regRole==='family'?35:18,'number')}<label>Documento de ejemplo<input type="file" accept="image/*" capture="environment"></label><label>Selfie de ejemplo<input type="file" accept="image/*" capture="user"></label>`}${btn('Simular verificación aprobada','','primary')} ${btn('Terminar más tarde',"laterVerification()",'ghost')}${er?notice('Las entidades quedan en revisión hasta que el administrador aprueba el CIF o licencia.'):''}</form>${S.verified?badge('Identidad verificada en la demo'):badge('Verificación pendiente',true)}</div>`}
function laterVerification(){S.verified=false;save();modal({title:'Completar desde otro móvil',body:`<p>Enlace de demostración para retomar la verificación:</p><input readonly value="${location.origin}/#verification">${btn('Copiar enlace',"copy(location.origin+'/#verification')")}${notice('No se ha enviado un correo real.')}`})}
function childadd(){if(S.role!=='family'&&regRole!=='family')return notice('Solo el tutor puede añadir hijos.');return `<div class="compact"><h1>Añadir jugador</h1><form class="card" id="child-form"><div class="fields">${input('name','Nombre y apellidos')}${input('dob','Fecha de nacimiento','','date')}${input('position','Posición principal')}${input('club','Club')}${select('category','Categoría',['Prebenjamín','Benjamín','Alevín','Infantil'])}${input('username','Usuario del jugador')}${input('password','Contraseña de acceso','','password')}</div><label><input type="checkbox" name="consent" required>Declaro que soy su tutor legal y autorizo su participación en la demo.</label>${notice('Privado por defecto. Podrás abrirlo a profesionales verificados desde Familia.')} ${btn('Crear acceso del jugador','','primary')}</form></div>`}
function upload(){return `<div class="compact"><h1>Publicar vídeo</h1>${!S.verified?notice('Necesitas verificar tu identidad antes de publicar.'):''}<form id="upload-form" class="card"><label>Elegir o grabar vídeo<input name="file" type="file" accept="video/*" capture="environment" required></label>${area('desc','Descripción')}${select('type','Tipo de contenido',['Partido','Entrenamiento','Highlights','Gol','Asistencia','Skill'])}<label><input name="pin" type="checkbox">Fijar en mi perfil (máximo tres)</label><p class="muted">Visibilidad: ${S.role==='child'?'la definida por tu tutor':S.privacy[S.role]||'la de tu perfil'}. Un vídeo nunca es más público que su autor.</p>${notice('El archivo se reproduce en este navegador. La conversión y el filtro automático se simulan; no se sube a Cloudflare Stream.')} ${btn('Publicar y pasar a revisión','','primary')}</form></div>`}
function myvideos(){return `<div class="row between"><h1>Mis vídeos</h1>${btn('Nuevo vídeo',"go('upload')",'primary')}</div>${S.videos.map(v=>`<div class="card"><div class="row between"><h3>${esc(v.desc)}</h3>${badge(v.status,v.status!=='Publicado')}</div><p>${esc(v.type)} · ${v.views} reproducciones</p>${v.status==='Retirado'?`<p>Motivo: ${esc(v.reason)}</p>${btn('Presentar recurso',`appeal(${v.id})`)}`:''}<div class="row">${v.status==='Publicado'?btn(v.pin?'Desfijar':'Fijar',`pinVideo(${v.id})`):''}${v.status==='En revisión'?btn('Ver estado de revisión',"toast('Pendiente del filtro automático simulado y de revisión en Administración.')"):''}</div></div>`).join('')}`}
function pinVideo(id){const v=S.videos.find(v=>v.id===id);if(!v.pin&&S.videos.filter(v=>v.pin).length>=3)return toast('Puedes fijar como máximo tres vídeos.');v.pin=!v.pin;save();render()}function appeal(id){modal({title:'Recurrir retirada',body:`<form onsubmit="event.preventDefault();S.reports.unshift({id:Date.now(),target:'Vídeo ${id}',reason:'Recurso',details:data(this).details,status:'Pendiente'});save();document.querySelector('#modal').close();toast('Recurso enviado al equipo')">${area('details','Explica por qué solicitas la revisión')}${btn('Enviar recurso','','primary')}</form>`})}
function statsedit(){if(!canEdit())return notice('Solo el jugador o tutor puede editar estas estadísticas.');const s=S.stats;return `<div class="compact"><h1>Estadísticas de temporada</h1>${notice('Estos datos se muestran como no verificados y no se utilizan para ordenar el Radar.')}<form id="stats-form" class="card"><div class="fields">${input('season','Temporada',s.season)}${input('club','Club',s.club)}${input('category','Categoría',s.category)}${[['games','Partidos'],['starts','Titularidades'],['minutes','Minutos'],['goals','Goles'],['assists','Asistencias'],['cards','Tarjetas']].map(([k,l])=>input(k,l,s[k],'number')).join('')}</div>${input('url','Enlace a la ficha federativa',s.url,'url',false)}${btn('Guardar estadísticas','','primary')}</form></div>`}
function profileedit(){return `<div class="compact"><h1>Editar perfil</h1><form id="profile-form" class="card"><div class="fields">${input('name','Nombre',S.profile.name)}${input('province','Provincia',S.profile.province)}${input('position','Posición principal',S.profile.position)}${input('secondary','Posición secundaria',S.profile.secondary,'text',false)}${input('club','Club',S.profile.club)}</div><label>Foto<input name="photo" type="file" accept="image/*"></label>${area('bio','Sobre mí',S.profile.bio)}${btn('Guardar cambios','','primary')}</form></div>`}
function admin(){if(S.role!=='admin')return `<h1>Administración</h1>${notice('Panel independiente reservado al equipo de TALNT. En este prototipo se puede probar con el selector de rol.')} ${btn('Entrar como administrador de demo',"changeRole('admin')",'primary')}`;return `<span class="eyebrow">TALNT · Equipo interno</span><h1>Panel de administración</h1>${tabs(['Verificaciones','Vídeos marcados','Denuncias','Recursos','Usuarios','Oportunidades','Registro'],tab||'Verificaciones')} ${adminContent(tab||'Verificaciones')}`}
function adminContent(t){if(t==='Registro')return `<div class="card"><h2>Registro de decisiones</h2>${S.audit.map(a=>`<div class="list-row"><div>${esc(a.text)}<p><small>${esc(a.by)} · ${esc(a.time)}</small></p></div></div>`).join('')||'<p>Sin decisiones todavía.</p>'}</div>`;if(t==='Verificaciones')return `<div class="card"><h2>Entidades pendientes</h2><p>Club Demo Sevilla · CIF de demostración</p>${badge(S.entityDecision||'Pendiente')}<p>Representante con identidad verificada. Documento: licencia federativa de ejemplo.</p><div class="row">${['Aprobar','Rechazar','Pedir más datos'].map(a=>btn(a,`adminDecision('Verificación Club Demo Sevilla','${a}')`)).join('')}</div><h3 style="margin-top:25px">Personas con incidencia</h3><p>Identidad Demo · selfie pendiente de revisión</p>${btn('Revisar incidencia',"adminDecision('Identidad Demo','Aprobar')")}<h3 style="margin-top:25px">Historial</h3>${S.audit.filter(a=>/Verificación|Identidad/.test(a.text)).map(a=>`<p>${esc(a.text)} · ${esc(a.time)}</p>`).join('')||'<p class="muted">Sin decisiones registradas.</p>'}</div>`;if(t==='Vídeos marcados')return S.videos.filter(v=>v.status==='En revisión').map(v=>`<div class="card"><h2>${esc(v.desc)}</h2><p>Autor: ${esc(v.name)} · edad demo: 18 · tutor: no aplica.</p><p>Filtro simulado: requiere revisión humana. Historial: sin sanciones.</p>${runtimeMedia[v.id]?`<video src="${runtimeMedia[v.id]}" controls style="max-width:100%;max-height:300px"></video>`:''}<div class="row">${['Aprobar y publicar','Retirar','Retirar y avisar','Suspender','Expulsar'].map(a=>btn(a,`moderateVideo(${v.id},'${a}')`)).join('')}</div></div>`).join('')||'<div class="empty">No hay vídeos pendientes de revisión.</div>';if(t==='Denuncias'||t==='Recursos')return S.reports.filter(r=>t==='Recursos'?r.reason==='Recurso':r.reason!=='Recurso').sort((a,b)=>Number(b.priority)-Number(a.priority)).map(r=>`<div class="card">${badge(r.priority?'Prioridad: menor':r.status)}<h2 style="margin-top:15px">${esc(r.target)}</h2><p>${esc(r.reason)}</p><p>${esc(r.details)}</p><div class="row">${['Aprobar','Retirar','Avisar','Suspender','Expulsar','Desestimar'].map(a=>btn(a,`resolveReport(${r.id},'${a}')`)).join('')}</div></div>`).join('')||'<div class="empty">La cola está vacía.</div>';if(t==='Usuarios')return `<div class="grid">${players.map(p=>`<div class="card"><h2>${esc(p.name)}</h2><p>${p.age} años · ${esc(p.club)}</p>${badge(S.blocked.includes(p.name)?'Suspendido':'Activo')}<div class="row" style="margin-top:15px">${btn('Ver perfil',`go('profile',${p.id})`)}${btn('Suspender',`S.blocked.push('${p.name}');log('Usuario ${p.name}: suspensión');render()`)}${btn('Expulsar',`adminDecision('Usuario ${p.name}','Expulsar')`,'danger')}</div></div>`).join('')}</div>`;if(t==='Oportunidades')return S.ops.map(o=>`<div class="card"><div class="row between"><h2>${esc(o.title)}</h2>${badge(o.status)}</div><div class="row">${btn('Ver',`go('opdetail',${o.id})`)}${btn('Editar',`opForm(${o.id})`)}${btn('Pausar',`setOp(${o.id},'Pausada')`)}${btn('Cerrar',`setOp(${o.id},'Cerrada')`)}</div></div>`).join('')}
function adminDecision(target,a){modal({title:a,body:`<form onsubmit="event.preventDefault();S.entityDecision='${a}';if('${a}'==='Aprobar')S.verified=true;log('${esc(target)}: ${a} · '+data(this).reason);document.querySelector('#modal').close();render();toast('Decisión registrada')">${area('reason','Motivo de la decisión')}${btn('Confirmar decisión','','primary')}</form>`})}function moderateVideo(id,a){modal({title:a,body:`<form onsubmit="event.preventDefault();finishModeration(${id},'${a}',data(this).reason)">${area('reason','Motivo visible para el usuario')}${btn('Confirmar','','primary')}</form>`})}function finishModeration(id,a,reason){let v=S.videos.find(v=>v.id===id);v.status=a==='Aprobar y publicar'?'Publicado':'Retirado';v.reason=reason||a;S.notifications.unshift({type:'actividad',text:`Tu vídeo: ${v.status}. ${v.reason}`});log(`Vídeo ${id}: ${a} · ${v.reason}`);$('#modal').close();render();toast('Decisión registrada')}
function resolveReport(id,a){const r=S.reports.find(r=>r.id===id);r.status=a;log(`${r.target}: ${a}`);if(r.reason==='Recurso'&&a==='Aprobar'){const v=S.videos.find(v=>'Vídeo '+v.id===r.target);if(v)v.status='Publicado';save()}render();toast('Decisión registrada')}
function scope(){const groups=[['A · Acceso y registro','Escaparate de 5 vídeos, tipo de cuenta, datos, documento y selfie, revisión de entidades, alta de hijos, suscripción.'],['B–C · Inicio y publicación','World TALNT / Siguiendo, publicar, comentarios, likes, compartir, guardar, fijar tres vídeos, revisión, retirada y recurso.'],['D · Radar / Buscar','Filtros completos, orden por actividad / edad / cercanía, una lista de guardados y búsqueda por nombre para jugadores.'],['E · Mensajes','Conversaciones, filtros, solicitudes, tres acciones TALNT, aprobación, chat, adjuntos, compartir, denuncias y bloqueo.'],['F · Oportunidades','Listado, filtros, guardadas, detalle, ubicación, solicitudes, estados, publicación y gestión de candidaturas.'],['G · Perfiles y familia','Jugador, club / academia / agencia, scouter / entrenador / staff, estadísticas, trayectoria, enlace / QR, panel de familia.'],['H · Seguridad y ajustes','Notificaciones, visibilidad según edad, suscripción, sesiones, eliminación, documentos legales, denuncia y bloqueo.'],['I · Administración','Verificación de entidades, incidencias, moderación de vídeos, denuncias prioritarias de menores, recursos, usuarios, sanciones, oportunidades y registro.']];return `<h1>Alcance del prototipo</h1>${notice('Referencia: propuesta Octonove de septiembre de 2026, 25 páginas. Es un prototipo funcional local, no un servicio multiusuario en producción.')}<div class="grid two">${groups.map(([n,d])=>`<div class="card"><h2>${n}</h2><p>${d}</p></div>`).join('')}</div><div class="card"><h2>Qué se simula</h2><p>Didit, moderación automática, Cloudflare Stream, pagos Apple / Google / Stripe, correo, push, sesión única entre dispositivos y traspaso a los 14 años. Sin cobros ni documentos reales. Las publicaciones locales se reproducen durante esta sesión; al recargar hay que volver a elegir el archivo.</p><p>Los cambios de formularios, guardados, solicitudes y moderación se guardan en este navegador. No se sincronizan entre PC y móvil.</p><p>Las decisiones del apartado 10.2 se utilizan como supuestos de diseño para poder recorrer los flujos; siguen pendientes de vuestro visto bueno. Precios y textos legales siguen pendientes.</p></div><div class="card"><h2>Fase siguiente según el proveedor</h2><p>Recompensas automáticas por referidos, ventajas anuales, búsqueda por hashtag / tipo de vídeo, concursos, descuentos de marcas, varias listas, comparador, secciones automáticas del Radar, oportunidades publicadas por profesionales y licencias por usuario.</p><h3>Más adelante</h3><p>Estados Unidos e inglés, estadísticas federativas por acuerdo y recomendación personalizada.</p><p class="muted">No se incluyen como funcionalidades activas del primer lanzamiento. TALNT Scout Score queda descartado.</p></div><div class="card"><h2>Pantallas de profesionales</h2><div class="row">${btn('Perfil de club',"go('orgprofile',1)")}${btn('Perfil de academia',"go('orgprofile',2)")}${btn('Perfil de agencia',"go('orgprofile',3)")}${btn('Perfil de scouter',"go('proprofile')")}</div></div>${btn('Reiniciar todos los datos de demo',"resetDemo()",'danger')}`}
function resetDemo(){modal({title:'Reiniciar demo',body:`<p>Se restaurarán los datos ficticios iniciales en este navegador.</p>${btn('Reiniciar',"S=structuredClone(initial);save();document.querySelector('#modal').close();go('home');toast('Demo reiniciada')",'danger')}`})}
function copy(t){navigator.clipboard?.writeText(t).then(()=>toast('Enlace copiado')).catch(()=>toast('Selecciona y copia el enlace manualmente.'))}
function share(name,route,id){const url=location.origin+location.pathname+'#'+route+(id?'?id='+id:'');modal({title:'Compartir '+name,body:`<label>Enlace al perfil o contenido<input value="${esc(url)}" readonly></label><img class="qr" id="qr" alt="Código QR del enlace" src="${id&&id<6?'qr-'+route+'-'+id+'.svg':'qr-main.svg'}">${btn('Copiar enlace',`copy('${url}')`)}<p class="muted">Comparte el acceso al prototipo. Los datos siguen siendo locales a cada navegador.</p>`});}
function bindForms(){let f;const on=(id,fn)=>{f=$('#'+id);if(f)f.onsubmit=e=>{e.preventDefault();fn(e.target)}};on('chat-form',f=>sendChatText(selected,data(f).text));on('billing-form',f=>{log('Contratación web simulada: '+data(f).name);toast('Factura y pago simulados. No se ha realizado ningún cobro.')});on('login-form',f=>{S.role='player';S.verified=true;save();go('home');toast('Sesión de demostración iniciada')});on('recovery-form',f=>modal({title:'Enlace de recuperación',body:notice('Envío simulado a '+esc(data(f).email))+btn('Simular nueva contraseña',"document.querySelector('#modal').close();go('login')")}));on('register-form',f=>{regData=data(f);regStep=3;render()});on('verify-form',f=>{let d=data(f),inReg=f.dataset.register==='true';let r=inReg?regRole:S.role;if(+d.age<6){toast('La edad mínima es 6 años.');return}if(+d.age<14){regRole='family';S.role='family';S.verified=false;regStep=2;go('register');toast('El registro debe completarlo el tutor legal.');return}S.verified=!['club','academy','agency'].includes(r);if(inReg){S.role=r;if(regData.name)S.profile.name=regData.name;regStep=4}save();if(inReg)render();else{toast(S.verified?'Identidad aprobada en la demo':'Entidad pendiente de revisión');render()}});on('child-form',f=>{const d=data(f),age=Math.floor((Date.now()-new Date(d.dob))/(365.25*86400000));if(age<6||age>=14){toast('Este flujo es para jugadores de 6 a 13 años.');return}S.children.push({name:d.name.split(' ')[0]+(d.name.includes(' ')?' '+d.name.split(' ')[1][0]+'.':''),age,club:d.club,visible:false,premium:false,username:d.username,consentDate:new Date().toISOString()});S.role='family';log('Declaración de tutor registrada para '+d.name);go('family');toast('Jugador añadido con perfil privado')});on('upload-form',f=>{if(!guard())return;const d=data(f),file=f.elements.file.files[0];if(!file)return;if(d.pin&&S.videos.filter(v=>v.pin).length>=3){toast('Ya tienes tres vídeos fijados.');return}const id=Date.now();runtimeMedia[id]=URL.createObjectURL(file);S.videos.unshift({id,name:S.profile.name,type:d.type,desc:d.desc||file.name,status:'En revisión',pin:!!d.pin,views:0});save();go('myvideos');toast('Vídeo en revisión simulada. Apruébalo en Administración.')});on('stats-form',f=>{const d=data(f);if(Object.keys(d).some(k=>['games','starts','minutes','goals','assists','cards'].includes(k)&&+d[k]<0)){toast('Las estadísticas no pueden ser negativas.');return}if(+d.starts>+d.games){toast('Las titularidades no pueden superar los partidos.');return}S.stats={...d,updated:new Date().toLocaleString('es-ES')};log('Estadísticas editadas por '+roles[S.role]);selected=1;go('profile');tab='Estadísticas';render();toast('Estadísticas guardadas')});on('profile-form',f=>{Object.assign(S.profile,data(f));delete S.profile.photo;save();selected=1;go('profile');toast('Perfil actualizado')});}
let hash=location.hash.slice(1).split('?');view=hash[0]||'home';if(hash[1])selected=Number(new URLSearchParams(hash[1]).get('id'))||1;render();
